{"content":"import { createFileRoute, Link } from "@tanstack/react-router";
import { useState, type FormEvent } from "react";
import { Trash2 } from "lucide-react";
import { toast } from "sonner";
import { formatPrice } from "@/data/catalog";
import { COMPANY } from "@/data/company";
import { resolveLines, useStore } from "@/lib/store";

export const Route = createFileRoute("/quote")({
  head: () => ({
    meta: [
      { title: "Request a Quote | Pickrel Brothers Wholesale Supply, Dayton OH" },
      {
        name: "description",
        content:
          "Send Pickrel Brothers a quote request with your part list, job name, delivery date and plans. Upload POs, PDFs and photos — we'll price it and get back to you.",
      },
      { property: "og:title", content: "Request a Quote | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Submit a bid list, plans or a PO and get pricing from our inside sales team.",
      },
    ],
  }),
  component: QuotePage,
});

function QuotePage() {
  const { quoteList, cart, setQuoteQty, removeFromQuote, moveCartToQuote, submitQuote } = useStore();
  const lines = resolveLines(quoteList);
  const [confirmation, setConfirmation] = useState<string | null>(null);

  function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const data = new FormData(e.currentTarget);
    const id = submitQuote(String(data.get("jobName") ?? "Untitled job"));
    setConfirmation(id);
    toast.success(`Quote request ${id} submitted`);
  }

  if (confirmation) {
    return (
      <div className="container-page py-16">
        <div className="mx-auto max-w-xl rounded-md border border-border bg-card p-10 text-center shadow-card">
          <h1 className="font-display text-3xl font-bold uppercase text-navy">Quote request received</h1>
          <p className="mt-3 text-sm text-muted-foreground">
            Reference <span className="font-mono font-semibold text-foreground">{confirmation}</span>. Our
            inside sales team will price it and follow up. Urgent? Call {COMPANY.phone}.
          </p>
          <div className="mt-6 flex flex-wrap justify-center gap-3">
            <Link
              to="/account"
              className="rounded-md bg-navy px-5 py-2.5 text-sm font-semibold text-navy-foreground hover:bg-navy-muted"
            >
              View my quotes
            </Link>
            <Link
              to="/products"
              search={{ q: "", category: "", brand: "" }}
              className="rounded-md border border-input px-5 py-2.5 text-sm font-semibold text-navy hover:bg-secondary"
            >
              Keep shopping
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container-page py-10">
      <h1 className="font-display text-3xl font-bold uppercase text-navy">Request a Quote</h1>
      <p className="mt-2 max-w-3xl text-muted-foreground">
        Add products from the catalog, paste a bid list, or upload plans and a PO. We'll price it against
        your account.
      </p>

      <div className="mt-8 grid gap-8 lg:grid-cols-[1fr_380px]">
        <section className="rounded-md border border-border bg-card shadow-card">
          <div className="flex items-center justify-between border-b border-border px-5 py-3">
            <h2 className="font-display text-lg font-bold uppercase text-navy">Quote items</h2>
            {cart.length > 0 && (
              <button
                type="button"
                onClick={() => {
                  moveCartToQuote();
                  toast.success("Cart added to quote list");
                }}
                className="text-sm font-semibold text-sky hover:underline"
              >
                Add my cart ({cart.length})
              </button>
            )}
          </div>

          {lines.length === 0 ? (
            <p className="px-5 py-8 text-sm text-muted-foreground">
              No products added yet. Browse the{" "}
              <Link
                to="/products"
                search={{ q: "", category: "", brand: "" }}
                className="font-semibold text-sky hover:underline"
              >
                catalog
              </Link>{" "}
              or describe what you need in the notes below.
            </p>
          ) : (
            <ul className="divide-y divide-border">
              {lines.map((l) => (
                <li key={l.slug} className="flex flex-wrap items-center gap-4 px-5 py-4">
                  <div className="min-w-[200px] flex-1">
                    <p className="text-xs font-bold uppercase text-sky">{l.product.manufacturer}</p>
                    <p className="text-sm font-semibold text-foreground">{l.product.name}</p>
                    <p className="font-mono text-xs text-muted-foreground">{l.product.mfrPartNumber}</p>
                  </div>
                  <input
                    type="number"
                    min={1}
                    value={l.qty}
                    aria-label={`Quantity for ${l.product.name}`}
                    onChange={(e) => setQuoteQty(l.slug, Number(e.target.value))}
                    className="h-10 w-20 rounded-md border border-input bg-card px-2 text-sm"
                  />
                  <span className="w-24 text-right text-sm text-muted-foreground">
                    {formatPrice(l.product.price)}
                  </span>
                  <button
                    type="button"
                    onClick={() => removeFromQuote(l.slug)}
                    aria-label={`Remove ${l.product.name}`}
                    className="rounded p-2 text-muted-foreground hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" aria-hidden />
                  </button>
                </li>
              ))}
            </ul>
          )}
        </section>

        <form onSubmit={onSubmit} className="rounded-md border border-border bg-card p-6 shadow-card">
          <h2 className="font-display text-lg font-bold uppercase text-navy">Job & contact details</h2>
          <div className="mt-4 space-y-4">
            <Field label="Job / project name" name="jobName" required />
            <Field label="Requested delivery date" name="deliveryDate" type="date" />
            <Field label="Your name" name="name" required />
            <Field label="Company" name="company" />
            <Field label="Email" name="email" type="email" required />
            <Field label="Phone" name="phone" type="tel" />
            <label className="block text-sm font-semibold text-navy">
              Notes / bid list
              <textarea
                name="notes"
                rows={5}
                placeholder="Paste a takeoff list, part numbers or describe the application."
                className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground"
              />
            </label>
            <label className="block text-sm font-semibold text-navy">
              Upload plans, PDFs, POs or photos
              <input
                type="file"
                multiple
                className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-muted-foreground"
              />
            </label>
            <button
              type="submit"
              className="w-full rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted"
            >
              Submit quote request
            </button>
            <p className="text-xs text-muted-foreground">
              Submitted quotes appear under My Account. Uploaded files are attached to the request for our
              sales team.
            </p>
          </div>
        </form>
      </div>
    </div>
  );
}

function Field({
  label,
  name,
  type = "text",
  required = false,
}: {
  label: string;
  name: string;
  type?: string;
  required?: boolean;
}) {
  return (
    <label className="block text-sm font-semibold text-navy">
      {label}
      {required && <span className="text-destructive"> *</span>}
      <input
        name={name}
        type={type}
        required={required}
        className="mt-1 block h-11 w-full rounded-md border border-input bg-card px-3 text-sm text-foreground"
      />
    </label>
  );
}
